vec3 colorGrade(vec3 color) {
    // Create a sophisticated palette
    vec3 shadows = vec3(0.1, 0.12, 0.18);     // Dark blue-grey
    vec3 midtones = vec3(0.4, 0.42, 0.5);     // Medium purple-grey
    vec3 highlights = vec3(0.7, 0.72, 0.85);  // Light blue-grey

    float luminance = dot(color, vec3(0.299, 0.587, 0.114));
    vec3 graded = mix(shadows, midtones, smoothstep(0.0, 0.5, luminance));
    graded = mix(graded, highlights, smoothstep(0.5, 1.0, luminance));

    return graded;
}

void mainImage(out vec4 O, vec2 u) {
    vec2 R = iResolution.xy;
    vec2 uv = u/R;

    // Initialize output
    O = vec4(0.0);

    // Apply gaussian blur
    for (int k = 0; k < 25; k++) {
        vec2 offset = (vec2(k%5, k/5) - 2.0) / R;
        vec4 s = texture(iChannel0, uv + offset);
        O += gk1s[k] * s;
    }

    // Apply color grading
    O.rgb = colorGrade(O.rgb);

    // Add subtle vignette
    vec2 vignetteUV = uv * 2.0 - 1.0;
    float vignette = 1.0 - dot(vignetteUV, vignetteUV) * 0.3;
    O.rgb *= vignette;
}

#define rot(x) mat2(cos(x+vec4(0,11,33,0)))

//formulas for creating colors;
#define H(h)  (cos(  h + vec3(1,2,3)   )*.9 +  .2)
#define H2(h)  (  cos(  h*2. + vec3(1,2,0)   )*.7 + .2 )

//formula for mapping scale factor 
#define M(c)  log(1.+c)

#define R iResolution


vec3 sphRep(vec3 p) {

    float r = length(p);
    float theta = acos( p.z/(1.+r));
    float phi   = atan(p.y,p.x);

    float twirliness = 200.;
    if (iMouse.z >0. ) twirliness = 1000.;

    float ph = r/twirliness;
    theta = mod(theta,2.*3.14159265/2.);

    return vec3( r*cos(theta), r*sin(theta)*cos(phi+ph), r*sin(theta)*sin(phi+ph) ); 

}

void mainImage( out vec4 O, vec2 U) {

    O = vec4(0);

    vec3 c=vec3(0);
    vec4 rd = normalize( vec4(U-.5*R.xy, .7*R.y, R.y))*500.;

    float sc,dotp,totdist=0., tt=iTime+100., t=0.;

    for (float i=0.; i<120.; i++) {

        vec4 p = vec4( rd*totdist);

        p.xyz += vec3(0,0,-200.-10.*( min(10.,mod(iTime,30.))));
        p.xz *= rot( cos(tt/4.+1.));
        p.xy *= rot( cos(tt*.4+sin(tt*.2)));
        p.yzw = sphRep(p.xyz);
        sc = 1.; 

        vec4 w = p;

        for (float j=0.; j<11.; j++) {

            p = abs(p)*.68 ;
            dotp = max(1./dot(w,w),3.*sin(tt / 10.));
            sc *= dotp;
            p = p * dotp - vec4(.3,.8,0,.5); 

            w=p;

        }

        float dist = abs( length(p-vec4(0,.3,0,.5) ) - .4 )/sc ;
        float stepsize = dist/80.  ;     
        totdist += stepsize;

        c +=
             .03 * H2(  atan( p.w, p.z ) ) * exp(-totdist/10.)
           + .04 * H(M(sc)) *  exp(-i*i*stepsize*stepsize*10.);
    }

    c = 1. - exp(-c*c);
    O = ( vec4(c,0) );

}
